// the router is present in the running app and, if so, exposes the router hooks the
// interactivity integration relies on. When the router is absent, `optionalRouter` is
// `undefined` and `isRouterInstalled` is `false`, so the integration is skipped entirely.

type RouteInfo = { pathname: string };

export type OptionalRouter = {
  useRoute: () => unknown;
  useNavigation: () => { isFocused: () => boolean };
  useCurrentRouteInfo: () => RouteInfo;
};

// Lazily required so the package keeps working when `expo-router` is not installed.
declare function require(moduleName: string): any;

function detectRouter(): OptionalRouter | undefined {
  const globalExpo = (globalThis as { expo?: Record<string, unknown> }).expo;
  if (!globalExpo || !('router' in globalExpo)) {
    return undefined;
  }

  try {
    const router = require('expo-router');
    return {
      useRoute: router.useRoute,
      useNavigation: router.useNavigation,
      useCurrentRouteInfo: router.useRouteInfo,
    };
  } catch {
    return undefined;
  }
}

export const optionalRouter = detectRouter();

export const isRouterInstalled = optionalRouter != null;
