let initialized = false;

/**
 * Whether {@link initRouterIntegration} has already run.
 */
export function isInitialized(): boolean {
  return initialized;
}

/**
 * Registers the router navigation listeners used to track interactivity per route.
 * Returns a cleanup function that removes the listeners.
 */
export function initListeners(): () => void {
  return () => {};
}

/**
 * Wires up the router integration. Safe to call multiple times — listeners are only
 * registered on the first call.
 */
export function initRouterIntegration(): void {
  if (initialized) {
    return;
  }
  initialized = true;
  initListeners();
