import { optionalRouter } from './router';

/**
 * Router-aware variant of the interactivity marker. When the router is installed it
 * returns a function that tags `markInteractive` calls with the current route's
 * `pathname` and no-ops while the current screen is not focused. When the router is not
 * installed it returns `null` so callers can fall back to the plain marker.
 */
export function useObserveForRouter() {
  if (!optionalRouter) {
    return null;
  }

  optionalRouter.useRoute();
  const navigation = optionalRouter.useNavigation();
  const routeInfo = optionalRouter.useCurrentRouteInfo();

  return (options?: MetricAttributes) => {
    if (!navigation.isFocused()) {
      return;
    }
    return AppMetrics.markInteractive({ ...options, routeName: routeInfo.pathname });
  };
}
