import { initRouterIntegration } from './integrations/expo-router/init';
import { isRouterInstalled } from './integrations/expo-router/router';
import type { Config, ExpoObserveModuleType } from './types';

type ConfigureOptions = Config & {
  /**
   * When `true`, skips wiring up the automatic expo-router interactivity integration
   * even if the router is installed.
   *
   * @default false
   */
  disableRouterIntegration?: boolean;
};

export interface ExpoObserveProxyType extends Omit<ExpoObserveModuleType, 'configure'> {
  configure(options: ConfigureOptions): void;
}

const nativeModule = requireNativeModule<ExpoObserveModuleType>('ExpoObserve');

/**
 * A Proxy over the native Expo module. `configure` strips the `disableRouterIntegration`
 * flag before forwarding to the native module and conditionally initializes the router
 * integration. Every other property access falls through to the native module.
 */
const ExpoObserve = new Proxy(nativeModule, {
  get(target, property, receiver) {
    if (property === 'configure') {
      return ({ disableRouterIntegration, ...config }: ConfigureOptions = {}) => {
        target.configure(config);
        if (isRouterInstalled && !disableRouterIntegration) {
          initRouterIntegration();
        }
      };
    }
    return Reflect.get(target, property, receiver);
  },
}) as unknown as ExpoObserveProxyType;

